((window.LMT_BODY = window.LMT_BODY || {})["timemap"] = window.LMT_BODY["timemap"] || {})["hi"] = {"gregorian-1582-ten-days":"<h3>4 अक्टूबर, फिर 15 अक्टूबर</h3><p>पोप के राज्यों (पेपल स्टेट्स) और कैथोलिक इटली के अधिकांश हिस्से में, तथा स्पेन, पुर्तगाल और पोलैंड-लिथुआनिया में, गुरुवार 4 अक्टूबर 1582 के बाद शुक्रवार 15 अक्टूबर आया। बीच की दस तारीख़ें वहाँ कभी इस्तेमाल ही नहीं हुईं। सप्ताह के दिन पहले की तरह क्रम से चलते रहे (गुरुवार के बाद तब भी शुक्रवार ही आया), इसलिए केवल महीने की तारीख़ ने छलाँग लगाई। यह आदेश पोप ग्रेगरी तेरहवें के बुल <em>Inter gravissimas</em> से आया, जिस पर टस्कुलम (फ़्रास्काटी) में उस दिन हस्ताक्षर हुए जिसे आज हम 24 फ़रवरी 1582 कहते हैं। बुल के अपने तिथि-खंड में वर्ष 1581 लिखा है, क्योंकि वह देहधारण (इनकार्नेशन) का वर्ष 25 मार्च से गिनता है। फ़्रांस ने दो महीने बाद इसका अनुसरण किया और 9 दिसंबर 1582 से सीधे 20 दिसंबर पर पहुँच गया।</p><h3>हर साल ग्यारह मिनट</h3><p>45 ईसा पूर्व से लागू जूलियन कैलेंडर हर चौथे वर्ष एक लीप डे जोड़ता है, जिससे वर्ष की औसत लंबाई 365.25 दिन हो जाती है। उष्णकटिबंधीय वर्ष, यानी एक वसंत विषुव से अगले वसंत विषुव तक का समय, लगभग 365.2422 दिन का होता है। इसलिए जूलियन वर्ष लगभग 11 मिनट ज़्यादा लंबा है, और कैलेंडर में विषुव की तारीख़ लगभग हर 128 वर्ष में एक दिन पहले खिसक जाती है। 1582 तक वसंत विषुव लगभग 11 मार्च को पड़ने लगा था।</p><p>यह खिसकाव ईस्टर के कारण मायने रखता था, जो वसंत विषुव के दिन या उसके बाद की पहली पूर्णिमा के बाद आने वाले रविवार को पड़ता है। चर्च की तालिकाओं में यह विषुव 21 मार्च पर स्थिर था। बुल कहता है कि नाइसिया परिषद के धर्मपिताओं ने विषुव 21 मार्च (रोमन गणना में, अप्रैल के कैलेंड्स से पहले का बारहवाँ दिन) पर तय किया था, हालाँकि परिषद के बचे हुए दस्तावेज़ों में यह तारीख़ नहीं मिलती। सुधार का लक्ष्य विषुव को वापस 21 मार्च पर लाना था। इसीलिए तेरह के बजाय दस दिन हटाए गए: इसने 325 ईस्वी का आकाश बहाल किया, जूलियस सीज़र के समय का नहीं।</p><h3>लीप वर्ष का नया नियम</h3><p>खिसकाव दोबारा न हो, इसके लिए बुल ने हर चौथे वर्ष का लीप डे तो बनाए रखा, पर उन शताब्दी वर्षों में उसे हटा दिया जो 400 से विभाज्य नहीं हैं। उसी के शब्दों में, 1700, 1800 और 1900 लीप वर्ष नहीं होंगे, जबकि 1600 और 2000 होंगे। हर 400 वर्ष में तीन लीप डे हटाने से वर्ष की औसत लंबाई 365.2425 दिन हो जाती है, जो उष्णकटिबंधीय वर्ष से लगभग 27 सेकंड अधिक है। यह योजना कैलाब्रिया के चिकित्सक अलॉयसियस लिलियस (लुइजी लिलियो) ने बनाई थी, जिनकी मृत्यु 1576 में हुई। इसके बाद जेसुइट गणितज्ञ क्रिस्टोफ़र क्लावियस ने प्रकाशित रचनाओं में इसका बचाव किया और इसे समझाया।</p><h3>ब्रिटेन, 1752</h3><p>अधिकांश प्रोटेस्टेंट राज्यों ने बाद में बदलाव किया। ग्रेट ब्रिटेन और उसके उपनिवेशों ने कैलेंडर (न्यू स्टाइल) अधिनियम 1750 के तहत बदलाव किया: बुधवार 2 सितंबर 1752 के बाद गुरुवार 14 सितंबर आया। तब तक अंतर दस नहीं, ग्यारह दिन हो चुका था, क्योंकि 1700 जूलियन नियम के अनुसार लीप वर्ष था पर ग्रेगोरियन नियम के अनुसार नहीं। इसी अधिनियम ने इंग्लैंड, वेल्स, आयरलैंड और उपनिवेशों में वर्ष की शुरुआत 25 मार्च से हटाकर 1 जनवरी कर दी, इसलिए वहाँ 1751 केवल 25 मार्च से 31 दिसंबर तक चला। जॉर्ज वॉशिंगटन का जन्म पुरानी गणना के अनुसार 11 फ़रवरी 1731 को वर्जीनिया में हुआ था। नई शैली में वह तारीख़ 22 फ़रवरी 1732 है।</p><p>ब्रिटिश कर-वर्ष में आज भी यह जोड़ दिखता है। पहले यह लेडी डे, यानी 25 मार्च, को शुरू होता था। पूरे वर्ष का राजस्व बनाए रखने के लिए इसकी शुरुआत ग्यारह दिन आगे, 5 अप्रैल पर खिसका दी गई। 1800 में, जो पुराने कैलेंडर में लीप वर्ष था पर नए में नहीं, यह फिर खिसककर 6 अप्रैल पर आ गई, जो आज भी ब्रिटेन के कर-वर्ष का पहला दिन है।</p><h3>“हमें हमारे ग्यारह दिन लौटाओ”</h3><p>यह कहानी कि 1752 में भीड़ ने अपने ग्यारह दिन वापस माँगते हुए दंगे किए, किसी समकालीन स्रोत से पुष्ट नहीं होती। 1995 में <em>Past &amp; Present</em> में प्रकाशित एक लेख में इतिहासकार रॉबर्ट पूल ने इस कहानी का स्रोत मुख्यतः विलियम हॉगार्थ की पेंटिंग <em>An Election Entertainment</em> (लगभग 1755) में खोजा। यह पेंटिंग 1754 के कड़वाहट भरे ऑक्सफ़र्डशायर चुनाव के दौरान व्हिग पार्टी के एक भोज को दिखाती है। नीचे दाईं ओर टोरी पार्टी का एक छीना हुआ बैनर पड़ा है, जिस पर लिखा है “हमें हमारे ग्यारह दिन लौटाओ”। व्हिग उम्मीदवारों में से एक थे वाइकाउंट पार्कर, जो अर्ल ऑफ़ मैकल्सफ़ील्ड के पुत्र थे; अर्ल एक खगोलशास्त्री थे जिन्होंने अधिनियम पारित कराने में मदद की थी। विरोधियों ने पार्कर पर जो आरोप लगाए, उनमें कैलेंडर भी एक था। बाद के लेखकों ने चुनावी मज़ाक को भीड़ की हिंसा का दस्तावेज़ समझ लिया।</p><p>मानचित्र पर वेटिकन का ग्रेगोरियन लेबल पहली बार 15 अक्टूबर 1582 को और ब्रिटेन का 14 सितंबर 1752 को दिखाई देता है। इन दोनों दिनों पर जूलियन कैलेंडर, जिसे रूसी ऑर्थोडॉक्स चर्च आज भी मानता है, 5 अक्टूबर और 3 सितंबर दिखाता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1582-10-15\" data-cal=\"greg_va\">📅 रोम में 15 अक्टूबर 1582</button><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1752-09-14\" data-cal=\"greg_uk\">📅 ब्रिटेन में 14 सितंबर 1752</button></div>","russia-october-in-november":"<p>बोल्शेविकों ने <strong>25 अक्टूबर 1917</strong> को पेत्रोग्राद में सत्ता पर कब्ज़ा किया। यह तारीख़ जूलियन कैलेंडर की है, जिसे रूस तब भी इस्तेमाल करता था। यूरोप के अधिकांश हिस्से में चलने वाले ग्रेगोरियन कैलेंडर में वही दिन <strong>7 नवंबर</strong> था, और सोवियत संघ अपनी वर्षगांठ की परेड रेड स्क्वायर पर 7 नवंबर को ही करता था। उसी साल पहले ज़ार का तख़्ता पलटने वाली क्रांति की भी दो तारीख़ें हैं। पेत्रोग्राद में हड़तालें और महिलाओं के जुलूस 23 फ़रवरी को शुरू हुए थे, जो ग्रेगोरियन कैलेंडर में 8 मार्च था — अंतरराष्ट्रीय महिला दिवस।</p><h3>तेरह दिन कहाँ से आए</h3><p>जूलियन कैलेंडर 45 ईसा पूर्व में लागू हुआ। इसमें हर चौथे साल एक अधिक दिन जोड़ा जाता है, इसलिए इसका साल औसतन 365.25 दिन का होता है, जो सौर वर्ष से लगभग 11 मिनट लंबा है। 1582 में पोप ग्रेगरी तेरहवें के सुधार ने दस दिन हटा दिए और तय किया कि शताब्दी वर्ष तभी अधिवर्ष होंगे जब वे 400 से विभाज्य हों। 1700, 1800 और 1900 जूलियन कैलेंडर में अधिवर्ष थे, पर ग्रेगोरियन में नहीं, इसलिए अंतर 10 दिन से बढ़कर 11, फिर 12, और मार्च 1900 से 13 दिन हो गया।</p><h3>जनवरी 1918 का आदेश</h3><p>रूस में ईसा के जन्म से वर्ष गिनने की प्रथा 1 जनवरी 1700 से ही शुरू हुई थी। उससे पहले पीटर महान का रूस सृष्टि की रचना से वर्ष गिनता था, और तब चल रहा वर्ष 7208 था। महीने और तारीख़ें जूलियन ही रहीं। 24 जनवरी 1918 (पुरानी शैली) को जन कमिसार परिषद ने आदेश दिया कि 31 जनवरी के अगले दिन को 1 फ़रवरी के बजाय 14 फ़रवरी कहा जाएगा। अनुबंध या क़ानून के तहत जिन दायित्वों की समय-सीमा 1 से 14 फ़रवरी के बीच पड़ती थी, वे 13 दिन आगे खिसका दी गईं। 1 जुलाई 1918 तक दस्तावेज़ों में नई तारीख़ के बाद कोष्ठक में पुरानी तारीख़ देना ज़रूरी था। मानचित्र पर ग्रेगोरियन 14 फ़रवरी 1918 का जूलियन लेबल <em>1 февраля 1918 г. (ст. ст.)</em> है, यानी \"1 फ़रवरी 1918 (पुरानी शैली)\"। पुराने कैलेंडर के अनुसार रूस इस दिन को यही कहता।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1917-11-07\" data-cal=\"julian\">📅 जूलियन कैलेंडर में 7 नवंबर 1917</button><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1918-02-14\" data-cal=\"julian\">📅 14 फ़रवरी 1918: रूस का नई शैली वाला पहला दिन</button></div><h3>चर्च ने पुरानी शैली बनाए रखी</h3><p>रूसी ऑर्थोडॉक्स चर्च ने कैलेंडर नहीं बदला। पैट्रिआर्क तिखोन ने अक्टूबर 1923 में नई शैली अपनाने का आदेश दिया, लेकिन पादरियों और पैरिशों के विरोध के कारण कुछ ही हफ़्तों में उसे वापस ले लिया। चर्च आज भी अपने स्थिर पर्वों की तारीख़ें जूलियन कैलेंडर से तय करता है। क्रिसमस पुरानी शैली में 25 दिसंबर है, जो ग्रेगोरियन में 7 जनवरी है। 13–14 जनवरी की रात का <em>स्तारी नोवी गोद</em> (पुराना नया साल) जूलियन 1 जनवरी है। सर्बियाई, जॉर्जियाई और यरूशलम के चर्च तथा माउंट एथोस के मठ भी यही कैलेंडर मानते हैं। यूक्रेन के ऑर्थोडॉक्स चर्च ने 1 सितंबर 2023 को इसे छोड़ दिया और अब वह क्रिसमस 25 दिसंबर को मनाता है।</p><h3>यूनान, 1923</h3><p>यूनान अपना नागरिक कैलेंडर बदलने वाला यूरोप का आख़िरी देश था। वहाँ 15 फ़रवरी 1923 के बाद सीधे 1 मार्च 1923 आया। मार्च 1924 में यूनान के चर्च ने संशोधित जूलियन कैलेंडर अपनाया, जिसका प्रस्ताव मिलुतिन मिलानकोविच ने 1923 में कॉन्स्टेंटिनोपल के सम्मेलन में रखा था। इसकी स्थिर तारीख़ें 2800 तक ग्रेगोरियन कैलेंडर से मेल खाती हैं। यूनानी और रूसी चर्च आज भी ईस्टर की गणना जूलियन कैलेंडर से करते हैं।</p><h3>2100 के बाद चौदह दिन</h3><p>यह अंतर 13 दिन पर नहीं टिकेगा। 2100 जूलियन कैलेंडर में अधिवर्ष है, पर ग्रेगोरियन में नहीं। जूलियन 29 फ़रवरी 2100 ग्रेगोरियन 14 मार्च 2100 को पड़ेगा, और उसके बाद से अंतर 14 दिन होगा। पुरानी शैली का 2100 का क्रिसमस 8 जनवरी 2101 को पड़ेगा। 2200 में अंतर 15 दिन और 2300 में 16 दिन हो जाएगा। 2400 के दौरान भी यह 16 दिन ही रहेगा, क्योंकि वह वर्ष दोनों कैलेंडरों में अधिवर्ष है।</p>","islamic-lunar-year":"<h3>बारह चाँद, कोई अधिक मास नहीं</h3><p>इस्लामी, यानी हिजरी, कैलेंडर में 29 या 30 दिन के बारह चांद्र महीने होते हैं, मुहर्रम से ज़ुल-हिज्जा तक। बारह चांद्र मास मिलकर लगभग 354.37 दिन बनते हैं, इसलिए हिजरी वर्ष 354 या 355 दिन का होता है, जो सौर वर्ष से लगभग 11 दिन छोटा है। क़ुरआन 9:36 वर्ष को बारह महीनों का ठहराता है, और 9:37 <em>नसी</em> की निंदा करता है। यह इस्लाम-पूर्व अरब की एक प्रथा थी जिसके ठीक स्वरूप पर मतभेद है: या तो यह वर्ष को ऋतुओं के साथ बनाए रखने के लिए एक अतिरिक्त महीना जोड़ना था, या किसी पवित्र महीने को आगे खिसका देना। जो भी हो, हिजरी कैलेंडर में कोई तेरहवाँ महीना नहीं है, जबकि यही युक्ति हिब्रू और चीनी चांद्र-सौर कैलेंडरों को सूर्य के साथ तालमेल में रखती है।</p><h3>रमज़ान खिसकता है</h3><p>वर्ष छोटा होने के कारण हर हिजरी तिथि ग्रेगोरियन वर्ष में लगभग 11 दिन पीछे खिसकती जाती है। सऊदी अरब की उम्म अल-क़ुरा तालिका में 1 रमज़ान 1446, 1 मार्च 2025 को पड़ा और 1 रमज़ान 1447, 18 फ़रवरी 2026 को; दोनों बार रोज़ों की घोषित शुरुआत तालिका से मेल खाई। तेरह साल पहले तालिका ने 1 रमज़ान 1434 को 9 जुलाई 2013 पर रखा था। उस शाम चाँद नहीं दिखा, इसलिए सऊदी अरब ने रोज़े 10 जुलाई से शुरू किए, उत्तरी गोलार्ध की गर्मियों के सबसे लंबे दिनों में। तालिका में 1 रमज़ान 1413, 22 फ़रवरी 1993 था, यानी 2026 की तारीख़ से लगभग ठीक 33 वर्ष पहले। उन 33 ग्रेगोरियन वर्षों में 34 हिजरी वर्ष बीत गए।</p><h3>वर्ष 1 यात्रा से पहले शुरू होता है</h3><p>यह संवत हिजरत से गिना जाता है, यानी 622 ईसवी में मुहम्मद के मक्का से मदीना जाने से, लेकिन वर्ष 1 यात्रा के दिन से शुरू नहीं होता। यह गणना ख़लीफ़ा उमर के समय, लगभग 17 हिजरी (638 ईसवी) में तय की गई थी। इसे उस चांद्र वर्ष की शुरुआत से गिना जाता है जिसमें हिजरत हुई: 1 मुहर्रम 1 हिजरी, जो जूलियन कैलेंडर में शुक्रवार 16 जुलाई 622 है, या मानचित्र में प्रयुक्त प्रोलेप्टिक ग्रेगोरियन कैलेंडर में 19 जुलाई। मुहम्मद लगभग दो महीने बाद, रबी-उल-अव्वल में, मदीना पहुँचे। अंकगणितीय तालिकाएँ एक दिन पहले का एक \"खगोलीय\" आरंभ-बिंदु भी इस्तेमाल करती हैं: गुरुवार 15 जुलाई।</p><h3>देखकर या गणना से</h3><p>पारंपरिक नियम के अनुसार महीना तब शुरू होता है जब 29 तारीख़ को सूर्यास्त के बाद पश्चिमी आकाश में नया चाँद दिख जाए। अगर वह न दिखे, तो महीना 30 दिन का होता है। नतीजतन पड़ोसी देश, या एक ही शहर की दो मस्जिदें भी, अलग-अलग दिनों पर रमज़ान शुरू कर सकती हैं। इसके विपरीत, सऊदी अरब का उम्म अल-क़ुरा कैलेंडर गणना से तैयार होता है, रियाद स्थित किंग अब्दुलअज़ीज़ सिटी फ़ॉर साइंस ऐंड टेक्नोलॉजी में। 1423 हिजरी (2002) से इसका नियम इस प्रकार है: 29 तारीख़ को यदि युति (अमावस्या) सूर्यास्त से पहले हो जाए और मक्का में चंद्रमा सूर्य के बाद अस्त हो, तो अगले दिन से नया महीना शुरू होता है। आर. एच. वान गेंट की गणना के अनुसार, लगभग हर चार में से तीन शामों को उस समय भी नया चाँद नंगी आँखों से नहीं दिखता।</p><p>यह तालिका नागरिक कामकाज के लिए इस्तेमाल होती है। रमज़ान, शव्वाल और ज़ुल-हिज्जा के लिए, और कुछ वर्षों में मुहर्रम के लिए भी, अधिकारी चाँद दिखने की रिपोर्टों के आधार पर निर्णय लेते हैं। 1427 हिजरी में तालिका ने 1 रमज़ान को 24 सितंबर 2006 पर रखा था, पर घोषित तारीख़ 23 सितंबर थी। जब किसी घोषणा से कोई महीना 31 दिन का रह जाता है, तो एक दिन दो बार गिना जाता है: 28 और 29 दिसंबर 2007 दोनों 19 ज़ुल-हिज्जा 1428 थे। मानचित्र इन घोषणाओं का नहीं, बल्कि प्रकाशित तालिका का अनुसरण करता है।</p><h3>बोहरा तालिका</h3><p>दाऊदी बोहरा एक शिया इस्माइली समुदाय है, जिसकी अनुमानित आबादी दस से पंद्रह लाख है और जिसके सबसे बड़े केंद्र गुजरात और मुंबई में हैं। वे मिस्र के फ़ातिमी ख़लीफ़ाओं से विरासत में मिले एक स्थिर अंकगणितीय कैलेंडर का उपयोग करते हैं। विषम संख्या वाले महीने 30 दिन के और सम संख्या वाले 29 दिन के होते हैं। हर 30 में से 11 वर्षों में (चक्र के वर्ष 2, 5, 8, 10, 13, 16, 19, 21, 24, 27 और 29) ज़ुल-हिज्जा में 30वाँ दिन जोड़ा जाता है। चक्र 10,631 दिन लंबा है, जिससे औसत महीना 29.53056 दिन का बनता है, जबकि खगोलीय औसत 29.53059 है। चूँकि तालिका चाँद का इंतज़ार नहीं करती, बोहरा त्योहार बाकी सबसे पहले आ सकते हैं। बोहराओं ने 1445 की ईद-उल-फ़ित्र 9 अप्रैल 2024 को मनाई, सऊदी अरब ने 10 अप्रैल को, और भारत के अधिकांश हिस्से ने 11 अप्रैल को। 18 फ़रवरी 2026 को मानचित्र बोहराओं के लिए ٢ رمضان ١٤٤٧ هـ और सऊदी अरब में ١ رمضان ١٤٤٧ هـ दिखाता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"2026-02-18\" data-cal=\"islamic\">📅 18 फ़रवरी 2026: 1 रमज़ान 1447</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"islamic\">🗓️ सऊदी उम्म अल-क़ुरा कैलेंडर</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"bohra\">🗓️ दाऊदी बोहरा कैलेंडर</button></div><h3>ईरान का सौर हिजरी</h3><p>ईरान भी उसी हिजरत से गिनती करता है, लेकिन सौर वर्षों में। 31 मार्च 1925 (11 फ़रवरदीन 1304) के एक क़ानून ने सौर हिजरी कैलेंडर को आधिकारिक बनाया। इसमें फ़ारसी नामों वाले बारह महीने हैं, और इसका वर्ष मार्च विषुव के दिन शुरू होता है, या अगर विषुव तेहरान में दोपहर के बाद पड़े तो अगले दिन। चूँकि सौर वर्ष चांद्र वर्ष से लगभग 11 दिन लंबा होता है, दोनों गणनाओं में अब 43 वर्ष का अंतर है: 29 अक्टूबर 2026 को मानचित्र ईरान में ۷ آبان ۱۴۰۵ और सऊदी अरब में ١٨ جمادى الأولى ١٤٤٨ هـ दिखाता है। रमज़ान, मुहर्रम और अन्य धार्मिक तिथियों के लिए ईरान अब भी चांद्र हिजरी कैलेंडर का ही उपयोग करता है।</p>","hebrew-leap-month":"<h3>बारह चाँद, ग्यारह दिन कम</h3><p>29 या 30 दिनों के बारह चांद्र महीने मिलकर लगभग 354 दिन बनते हैं, जो सौर वर्ष से ग्यारह दिन कम है। इस्लामी कैलेंडर इस कमी को स्वीकार कर लेता है, और उसके त्योहार लगभग 33 वर्षों में हर ऋतु से होकर गुज़र जाते हैं। हिब्रू कैलेंडर ऐसा नहीं कर सकता। पासओवर (पेसख़) 15 निसान को पड़ता है, और व्यवस्थाविवरण 16:1 उसे <em>अवीव</em> के महीने से, यानी वसंत में पकती जौ के समय से, जोड़ता है। इसलिए हर 19 में से 7 वर्षों में कैलेंडर एक तेरहवाँ महीना जोड़ता है। उन्नीस सौर वर्ष लगभग 6,939.60 दिन के होते हैं और 235 चांद्र महीने (19 × 12 + 7) लगभग 6,939.69 दिन के, इसलिए कैलेंडर ऋतुओं की तुलना में हर 216 वर्षों में लगभग एक दिन आगे खिसक जाता है। हर चक्र के 3, 6, 8, 11, 14, 17 और 19वें वर्ष अधिवर्ष होते हैं।</p><h3>कौन-सा अदार अतिरिक्त है</h3><p>अतिरिक्त महीना अदार से पहले जोड़ा जाता है, जो निसान से पहले का महीना है। अधिवर्ष में <strong>अदार I</strong> (אדר א׳, 30 दिन) के बाद <strong>अदार II</strong> (אדר ב׳, 29 दिन) आता है। अदार II को ही सामान्य अदार माना जाता है, इसलिए पूरिम 14 अदार II को मनाया जाता है। वर्ष 5787, जो 12 सितंबर 2026 को शुरू हुआ, अपने चक्र का 11वाँ वर्ष है। मानचित्र पर 1 अदार I 5787 की तारीख़ 8 फ़रवरी 2027 है, 1 अदार II की 10 मार्च, पूरिम की 23 मार्च और पासओवर की 22 अप्रैल। हिब्रू दिन सूर्यास्त से शुरू होता है, इसलिए इनमें से हर त्योहार मानचित्र पर दिखाई गई तारीख़ से पहले वाली शाम को शुरू हो जाता है। सामान्य वर्ष 353, 354 या 355 दिनों का होता है और अधिवर्ष 383, 384 या 385 दिनों का। वर्ष 5786 में 354 दिन थे, और 5787 में 385 हैं।</p><h3>सातवें महीने में नव वर्ष</h3><p>निर्गमन 12:2 वसंत के महीने निसान को महीनों में पहला ठहराता है, और महीनों की गिनती आज भी उसी से होती है, इसलिए तिशरी सातवाँ महीना है। फिर भी वर्ष की संख्या 1 तिशरी, यानी रोश हशाना को, सितंबर या अक्टूबर में बदलती है। मिश्ना (रोश हशाना 1:1) चार नव वर्ष गिनाती है:</p><ul><li>1 निसान, राजाओं और त्योहारों के लिए</li><li>1 एलूल, पशुओं के दशमांश के लिए</li><li>1 तिशरी, वर्षों, विश्राम-वर्षों और जुबली वर्षों के लिए</li><li>1 या 15 शेवात, पेड़ों के लिए (शम्माई और हिलेल के घराने इस पर असहमत हैं कि कौन-सा दिन)</li></ul><p>वर्ष <em>अन्नो मुंडी</em> (सृष्टि संवत) में गिने जाते हैं, यानी सृष्टि की उस तारीख़ से, जिसे गणना 3761 ईसा पूर्व की शरद ऋतु में रखती है।</p><h3>वर्ष को अक्षरों में लिखना</h3><p>मानचित्र तारीख़ें हिब्रू अक्षर-अंकों में लिखता है। रोश हशाना 5787 <strong>א׳ בתשרי תשפ״ז</strong> के रूप में दिखता है, यानी 1 तिशरी 5787। वर्ष संख्या में ת = 400, ש = 300, פ = 80 और ז = 7 हैं, जिनसे 787 बनता है। हज़ार छोड़ दिए जाते हैं; पूरे रूप ה׳תשפ״ז में ה = 5 और जुड़ता है। दोहरी रेखा ״ (<em>गेरशायिम</em>) अंतिम अक्षर से पहले लगाई जाती है। पंद्रह को י״ה (10 + 5) नहीं, बल्कि ט״ו (9 + 6) लिखा जाता है, क्योंकि वे दो अक्षर ईश्वर का एक नाम बनाते हैं, और इसी कारण 16 को ט״ז लिखा जाता है। इसलिए पासओवर 5787 मानचित्र पर ט״ו בניסן תשפ״ז के रूप में दिखता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"hebrew\">🗓️ मानचित्र पर हिब्रू कैलेंडर दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"2026-09-12\" data-cal=\"hebrew\">📅 रोश हशाना 5787 (12 सितंबर 2026)</button><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"2027-03-10\" data-cal=\"hebrew\">📅 1 अदार II 5787 (10 मार्च 2027)</button></div><h3>चाँद देखने से गणना तक</h3><p>कभी नए महीनों की घोषणा एक न्यायालय उन गवाहों की गवाही पर करता था जिन्होंने नया अर्धचंद्र देखा हो, और अधिवर्ष निर्णय द्वारा जोड़े जाते थे। हाई गाओन (मृत्यु 1038) पहले व्यक्ति हैं जिन्होंने यह परंपरा दर्ज की कि हिलेल द्वितीय ने सेल्यूसिड संवत के वर्ष 670, यानी 358/359 ईसवी में, गणना-आधारित कैलेंडर शुरू किया। इतिहासकार इन नियमों को इससे बाद का और चरणों में बना मानते हैं। रोश हशाना के नियमों ने लगभग 629 और 648 के बीच अपना आधुनिक रूप लिया। निश्चित 19-वर्षीय चक्र संभवतः 8वीं शताब्दी के अंतिम भाग का है। अल-ख़्वारिज़्मी ने 823 में इस प्रणाली का वर्णन काफ़ी हद तक उसके वर्तमान रूप में किया। 921 में फ़िलिस्तीन में आरोन बेन मेयर ने व्यवस्था दी कि तिशरी गणना से निकले नवचंद्र के दिन ही शुरू हो, जब तक वह दोपहर के बाद 642 भागों से अधिक देर से न आए। बेबीलोन की अकादमियों ने, जिनके प्रवक्ताओं में सादिया गाओन भी थे, दोपहर को ही सीमा बनाए रखा। 922 में दोनों समुदायों ने पासओवर दो दिन के अंतर से मनाया। मैमोनिडीज़ ने 1178 में अपनी <em>मिश्ने तोरा</em> में पूरे नियम प्रस्तुत किए।</p><h3>वे दिन जिन पर नव वर्ष नहीं पड़ सकता</h3><p>गणना <em>मोलाद</em> से शुरू होती है, यानी औसत नवचंद्र, जो हर 29 दिन 12 घंटे और 793 भागों पर दोहराता है; एक घंटे में 1,080 भाग होते हैं। यदि तिशरी का मोलाद दोपहर को या उसके बाद आता है, तो रोश हशाना अगले दिन पर चला जाता है। वह कभी रविवार, बुधवार या शुक्रवार को भी नहीं पड़ता। इस नियम को <em>लो अदू रोश</em> कहा जाता है, जो א, ד और ו अक्षरों से बना है; ये सप्ताह के दिन 1, 4 और 6 को दर्शाते हैं। यदि वर्ष बुधवार या शुक्रवार को शुरू होता, तो योम किप्पुर (10 तिशरी) सब्त से ठीक पहले या ठीक बाद वाले दिन पड़ता। यदि वह रविवार को शुरू होता, तो होशाना रब्बा (21 तिशरी), जिसमें विलो की टहनियाँ पीटने की रस्म होती है, सब्त के दिन पड़ता। दो और दुर्लभ नियम हर वर्ष को स्वीकृत लंबाइयों के भीतर रखते हैं। मानचित्र पर 1900 से 2100 के बीच 1 तिशरी 56 बार सोमवार को, 23 बार मंगलवार को, 63 बार गुरुवार को और 59 बार शनिवार को पड़ता है। यह किसी और दिन कभी नहीं पड़ता।</p>","japanese-era-names":"<h3>ताइका से ताइहो तक</h3><p>जापान का पहला युग-नाम, <strong>大化</strong> <em>ताइका</em> (\"महान परिवर्तन\"), 645 में घोषित हुआ, उसी वर्ष जब राजकुमार नाका नो ओए और नाकातोमी नो कामातारी ने सोगा कुल को सत्ता से उखाड़ फेंका। अगली आधी सदी तक युग-नामों का प्रयोग केवल रुक-रुककर हुआ: 650 में 白雉 <em>हाकुची</em> आया, और उसके बाद लंबे अंतराल रहे। अटूट क्रम 701 में 大宝 <em>ताइहो</em> से शुरू होता है। मुख्य कैबिनेट सचिव योशिहिदे सुगा ने 1 अप्रैल 2019 को 令和 <em>रेइवा</em> की घोषणा की; प्रचलित गणना में यह 248वाँ युग है। इस गणना में उत्तरी और दक्षिणी दरबारों के काल (1336–1392) के दोनों प्रतिद्वंद्वी दरबारों के युग शामिल हैं, जब हर वंश-शाखा अपने अलग युग घोषित करती थी।</p><h3>एक शासनकाल, अनेक युग</h3><p>1868 से पहले दरबार जब भी कोई कारण देखता, युग बदल देता था: कोई शुभ शकुन, भूकंप, महामारी, या साठ वर्षीय चक्र के वे दो वर्ष जिनके बारे में माना जाता था कि वे उथल-पुथल लाते हैं, 辛酉 <em>कानोतो-तोरी</em> और 甲子 <em>किनोए-ने</em>। सम्राट कोमेई (शासनकाल 1846–1867) ने 1848 से 1865 के बीच छह नए युग घोषित किए: 嘉永 <em>काएई</em>, 安政 <em>आनसेई</em> (1854 के भूकंपों के बाद), 万延 <em>मान'एन</em>, 文久 <em>बुनक्यू</em> (1861, एक <em>कानोतो-तोरी</em> वर्ष), 元治 <em>गेनजी</em> (1864, एक <em>किनोए-ने</em> वर्ष) और 慶応 <em>केइओ</em>।</p><h3>एक शासनकाल, एक युग</h3><p>केइओ 4 के 9वें महीने के 8वें दिन (23 अक्टूबर 1868) के एक राजादेश ने पूरे केइओ 4 का नाम बदलकर मेइजी 1 कर दिया। उसी राजादेश ने यह भी तय किया कि हर शासनकाल का एक ही युग होगा, <strong>一世一元</strong> <em>इस्सेई इचिगेन</em>। 1889 के शाही परिवार क़ानून के अनुच्छेद 12 ने इस नियम को क़ानून का रूप दिया। तब से युग ही हर सम्राट का मरणोपरांत नाम भी बनता है, इसलिए मेइजी सम्राट का नाम उनके युग पर है। किसी युग का पहला वर्ष 1年 नहीं, बल्कि 元年 <em>गान्नेन</em> लिखा जाता है। मेइजी नियम के तहत नया युग राज्यारोहण के दिन से शुरू होता था: ताइशो 30 जुलाई 1912 को, जिस दिन मेइजी सम्राट का निधन हुआ, और शोवा 25 दिसंबर 1926 को, जिस दिन सम्राट ताइशो का निधन हुआ। शोवा 64 केवल सात दिन चला, 1–7 जनवरी 1989: सम्राट शोवा का 7 जनवरी को निधन हुआ, और अगले दिन, 8 जनवरी को, हेइसेई शुरू हुआ। मानचित्र 1 जनवरी 1873 (मेइजी 6) से जापानी युग की तिथियाँ दिखाता है। जापान ने मेइजी 5 के 12वें महीने के तीसरे दिन को यही तिथि बनाकर ग्रेगोरियन कैलेंडर अपनाया, और उससे पहले युग-वर्षों की गणना चांद्र-सौर कैलेंडर से होती थी।</p><h3>1979 का क़ानून</h3><p>1947 के युद्धोत्तर शाही परिवार क़ानून से युग-नामों वाला प्रावधान हटा दिया गया, इसलिए 1947 से शोवा केवल परंपरा के बल पर प्रयोग में रहा। <strong>युग-नाम क़ानून</strong> (元号法 <em>गेनगो-हो</em>, 12 जून 1979 का क़ानून संख्या 43) में दो प्रावधान हैं: युग-नाम कैबिनेट आदेश से तय होता है, और यह केवल तभी बदलता है जब कोई सम्राट गद्दी पर बैठता है। एक पूरक प्रावधान शोवा को इसी क़ानून के तहत तय हुआ मानता है। यह क़ानून निजी नागरिकों को युग-नामों का प्रयोग करने के लिए बाध्य नहीं करता। 平成 <em>हेइसेई</em> इसके तहत चुना गया पहला युग था, जो <em>शिजी</em> और <em>दस्तावेज़ों की पुस्तक</em> के वाक्यांशों से लिया गया।</p><h3>रेइवा</h3><p>सम्राट अकिहितो ने 30 अप्रैल 2019 को सिंहासन त्याग दिया; लगभग दो सौ वर्षों में यह सिंहासन-त्याग से हुआ पहला उत्तराधिकार था। चूँकि तिथि पहले से ज्ञात थी, नया नाम एक महीना पहले घोषित कर दिया गया। इसलिए 2019 का वर्ष 1 जनवरी से 30 अप्रैल तक हेइसेई 31 है और 1 मई से रेइवा 1। मानचित्र 平成31年4月30日 और फिर 令和元年5月1日 दिखाता है। सरकार ने रेइवा को, जहाँ तक अभिलेख बताते हैं, पहला ऐसा युग-नाम बताया जो किसी चीनी क्लासिक के बजाय किसी जापानी ग्रंथ से लिया गया। इसका स्रोत <em>मान्योशू</em> की पुस्तक 5 में बेर-पुष्पों पर बत्तीस कविताओं की प्रस्तावना है, जिसमें तेनप्यो 2 (730) के पहले महीने के 13वें दिन दाज़ाइफ़ु में ओतोमो नो ताबितो के निवास पर हुए एक भोज का वर्णन है: 初春令月、氣淑風和 \"आरंभिक वसंत के सुंदर महीने में, हवा निर्मल है और पवन कोमल\"। यह नाम उस गद्य प्रस्तावना से लिया गया है, किसी कविता से नहीं। प्रस्तावना चीनी भाषा में लिखी है, और टीकाकार इसके 令月 का स्रोत पूर्वी हान काल के कवि झांग हेंग (78–139) की रचना \"खेतों की ओर वापसी\" को मानते हैं, जो छठी सदी के <em>वेन श्वान</em> में सुरक्षित है और जिसमें 仲春令月、時和氣清 है। आठ में से पाँच अक्षर समान हैं। कुछ विदेशी रिपोर्टों द्वारा 令 का अर्थ \"आदेश\" बताए जाने के बाद, 2 अप्रैल 2019 को विदेश मंत्रालय ने नाम की अंग्रेज़ी व्याख्या के रूप में \"beautiful harmony\" (सुंदर सामंजस्य) दिया; मंत्रालय ने कहा कि यह अर्थ की व्याख्या है, आधिकारिक अनुवाद नहीं।</p><h3>शाही वर्ष</h3><p>ऐतिहासिक मोड में <strong>皇紀</strong> <em>कोकी</em> भी दिखता है, जो पौराणिक प्रथम सम्राट जिम्मू के राज्यारोहण से वर्षों की गणना है। सरकार ने इसे 1872 में अपनाया, और यह उस राज्यारोहण को 660 ईसा पूर्व में रखता है, जो <em>निहोन शोकी</em> के कालक्रम से ली गई तिथि है और जिसका कोई ऐतिहासिक आधार नहीं है। कोकी वर्ष पश्चिमी वर्ष में 660 जोड़ने पर मिलता है, इसलिए 1940 का वर्ष 2600 था। 10 नवंबर 1940 को शाही महल के सामने इस वर्षगाँठ का राजकीय समारोह हुआ, और उसी वर्ष अपनाए गए नौसेना के टाइप 0 वाहक-आधारित लड़ाकू विमान ने अपना \"0\" 2600 के अंतिम अंक से लिया।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"2019-05-01\" data-cal=\"japanese\">📅 1 मई 2019, रेइवा 1 पर जाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"koki\">🗓️ शाही वर्ष (कोकी) दिखाएँ</button></div>","ethiopian-13-months":"<h3>तीस-तीस दिनों के बारह महीने, और पागुमे</h3><p>इथियोपियाई वर्ष में ठीक 30-30 दिनों के बारह महीने होते हैं: मेस्केरेम, तिकिम्त, हिदार, तहसास, तिर, येकातित, मेगाबित, मियाज़िया, गिनबोत, सेने, हम्ले और नहासे। इनके बाद तेरहवाँ महीना <strong>पागुमे</strong> (ጳጉሜን) आता है। इसमें 5 दिन होते हैं, और हर चौथे वर्ष 6। यह नाम यूनानी <em>epagomenai</em> से आया है, जिसका अर्थ है \"जोड़े गए (दिन)\"; यूनानी-भाषी मिस्र में 360 के बाद बचे पाँच दिनों के लिए यही शब्द चलता था। अधिवर्ष के नियम में कोई अपवाद नहीं है, इसलिए यह जूलियन नियम ही है। 1 मेस्केरेम जूलियन कैलेंडर में हमेशा 29 अगस्त को पड़ता है, या जूलियन अधिवर्ष से पहले वाले वर्ष में 30 अगस्त को।</p><h3>एन्कुताताश 11 और 12 सितंबर के बीच क्यों खिसकता है</h3><p>1900 से 2099 के बीच जूलियन कैलेंडर ग्रेगोरियन से 13 दिन पीछे चलता है। इसलिए इथियोपियाई नववर्ष, <strong>एन्कुताताश</strong>, 11 सितंबर को पड़ता है। जब अभी-अभी समाप्त हुए इथियोपियाई वर्ष में पागुमे का छठा दिन रहा हो, तब यह 12 सितंबर पर चला जाता है; ऐसा ग्रेगोरियन अधिवर्ष से पहले वाले वर्ष में होता है। इथियोपियाई वर्ष 2019 ऐसा ही एक वर्ष है: 6 पागुमे 2019 को 11 सितंबर 2027 है, और 2020 का आरंभ 12 सितंबर 2027 को होता है। ग्रेगोरियन कैलेंडर 2100 में अधिदिन छोड़ देता है, पर इथियोपियाई कैलेंडर नहीं छोड़ता। सितंबर 2100 से नववर्ष 12 सितंबर को पड़ेगा, और ग्रेगोरियन अधिवर्ष से पहले वाले वर्ष में 13 सितंबर को।</p><h3>सात या आठ साल पीछे</h3><p>वर्ष-संख्याओं का अंतर अवतार की अलग तिथि के कारण है। लगभग 400 ई. में अलेक्ज़ान्द्रिया के एक भिक्षु अन्नियानस ने सृष्टि को 25 मार्च 5492 ई.पू. पर रखा और अवतार को उसके 5,500 वर्ष बाद, 25 मार्च 9 ई. पर। इथियोपिया का <em>Amätä Məḥrät</em>, यानी \"दया का वर्ष\", वर्ष-संख्या के बाद ዓ.ም. लिखकर संक्षेप में दर्शाया जाता है। इसकी गिनती उस मार्च से पहले आए अलेक्ज़ान्द्रियाई नववर्ष से होती है: 29 अगस्त 8 ई.। पश्चिमी ईस्वी गणना उस ईस्टर तालिका से चली आती है जिसे डायोनिसियस एक्सिगुअस ने 525 में रोम में तैयार किया था, और जिसमें गिनती एक पहले के अवतार से थी। परिणाम यह है कि 1 मेस्केरेम से 31 दिसंबर तक इथियोपियाई वर्ष ग्रेगोरियन वर्ष में से 7 घटाने पर मिलता है, और 1 जनवरी से एन्कुताताश की पूर्व संध्या तक ग्रेगोरियन वर्ष में से 8 घटाने पर। सृष्टि से गिनने वाली पुरानी चर्च गणना, <em>Amätä ʿAläm</em>, इसी वर्ष-संख्या में 5,500 जोड़ने पर मिलती है।</p><h3>2007 की सहस्राब्दी</h3><p>इथियोपियाई वर्ष 1999 में पागुमे के छह दिन थे। इसलिए नक्शा 11 सितंबर 2007 को <em>ጳጉሜን 6 ቀን 1999 ዓ.ም.</em> दिखाता है, और अगले दिन, बुधवार 12 सितंबर 2007 को, <em>መስከረም 1 ቀን 2000 ዓ.ም.</em>, यानी वर्ष 2000 का पहला दिन। इथियोपिया ने उस दिन को अपनी सहस्राब्दी के रूप में मनाया। AFP ने अदीस अबाबा में चल रही तैयारियों की ख़बर दी: 20,000 लोगों की क्षमता वाला एक अस्थायी स्थल, जिस पर कथित तौर पर 1 करोड़ डॉलर ($10 मिलियन) ख़र्च हुए, और $270 से $330 के कॉन्सर्ट टिकट, उस देश में जहाँ प्रति व्यक्ति औसत वार्षिक आय 2005 में अपने उच्चतम स्तर $160 पर पहुँची थी। हैले गेब्रसेलासी द्वारा आयोजित 10 किमी की मिलेनियम दौड़ की भी योजना थी।</p><h3>कॉप्टिक जुड़वाँ</h3><p>मिस्र के कॉप्टिक कैलेंडर की संरचना और अधिवर्ष-नियम वही हैं, और उसके महीने भी उन्हीं दिनों से शुरू होते हैं। 1 मेस्केरेम ही 1 तूत है, कॉप्टिक नववर्ष (नैरूज़)। अंतर केवल संवत् का है। कॉप्टिक शहीद संवत् 29 अगस्त 284 से गिना जाता है, जो डायोक्लेटियन के शासन के पहले वर्ष का आरंभ था; वह उसी वर्ष नवंबर में सम्राट बना था। यह इथियोपियाई आरंभ-बिंदु से 276 वर्ष बाद है। इस तरह 1 मेस्केरेम 2000 वही दिन है जो 1 तूत 1724, और नक्शे पर यह <em>١ توت ١٧٢٤ للشهداء</em> के रूप में दिखता है। दोनों कैलेंडर 12 × 30 + 5 दिनों वाले मिस्री नागरिक वर्ष से निकले हैं। ऑगस्टस के समय हुए अलेक्ज़ान्द्रियाई सुधार ने हर चौथे वर्ष छठा दिन जोड़ा।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"2007-09-12\" data-cal=\"ethiopic\">📅 12 सितंबर 2007 पर जाएँ, इथियोपियाई वर्ष 2000 का पहला दिन</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"coptic\">🗓️ कॉप्टिक कैलेंडर दिखाएँ</button></div><h3>धूप के तेरह महीने</h3><p><em>13 Months of Sunshine</em> (\"धूप के 13 महीने\") एक पर्यटन नारा है। हब्तेसेलासी तफ़ेसे (1927–2017) 1960 के दशक से इथियोपियाई पर्यटन संगठन के प्रमुख रहे, और 2017 में The Reporter में छपी उनकी श्रद्धांजलि इस नारे को गढ़ने का श्रेय उन्हें देती है। तेरहवाँ महीना पाँच या छह दिन का होता है। यह नारा मुख्य वर्षा ऋतु, <em>किरेम्त</em>, को भी नज़रअंदाज़ करता है, जो ऊँचे पठारी इलाक़ों में लगभग जून से सितंबर तक चलती है। पागुमे किरेम्त के अंत में पड़ता है, 6 से 10 सितंबर तक, या अधिवर्ष में 11 सितंबर तक।</p>","french-republican-calendar":"<h3>वर्ष I, पीछे की ओर गिना गया</h3><p>फ़्रांसीसी गणतंत्रीय कैलेंडर अपने वर्ष <strong>22 सितंबर 1792</strong> से गिनता है, यानी राष्ट्रीय कन्वेंशन द्वारा राजतंत्र समाप्त किए जाने के अगले दिन से। पेरिस में वही दिन शरद विषुव भी था, और कैलेंडर के निर्माताओं ने इस संयोग को नियमों में ही बाँध दिया: हर नया वर्ष उस दिन शुरू होना था जिस दिन पेरिस वेधशाला के लिए गणना किया गया वास्तविक शरद विषुव पड़े। इस व्यवस्था का आदेश 14 वांदेमियेर वर्ष II (5 अक्टूबर 1793) को जारी हुआ और 4 फ़्रिमेर वर्ष II (24 नवंबर 1793) को इसे अंतिम रूप मिला। तब तक वर्ष II चल रहा था, इसलिए वर्ष I का कोई भी दिन उस समय नए महीनों में दिनांकित नहीं हुआ। वर्ष-गणना स्वयं इससे पुरानी थी: 22 सितंबर 1792 से सरकारी दस्तावेज़ों पर ग्रेगोरियन महीनों के साथ <em>l'an premier de la République</em> (गणराज्य का पहला वर्ष) लिखा जाता था, और 2 जनवरी 1793 के एक आदेश ने वर्ष II की शुरुआत 1 जनवरी 1793 से कर दी थी; नए कैलेंडर ने यह शुरुआत खिसकाकर 22 सितंबर 1793 कर दी। इसे तैयार करने वाले आयोग का नेतृत्व सांसद जिल्बेर रोम ने किया था, और उसमें गणितज्ञ लाग्रांज और मोंज भी शामिल थे।</p><h3>तीस दिन के महीने, दस दिन के सप्ताह</h3><p>वर्ष में 30-30 दिनों के बारह महीने थे। हर महीना तीन <em>décades</em> (दकाद) में बँटा था, और दिनों को बस क्रमांक दिए गए थे: <em>primidi, duodi, tridi</em> से लेकर <em>décadi</em> तक, जो विश्राम का दिन था। वर्ष के अंत में बचे पाँच दिन, और अधिवर्ष में छह, <em>sansculottides</em> (सां-कुलोतीद) कहलाते थे: सद्गुण, प्रतिभा, श्रम, मत और पुरस्कार के उत्सव, और अधिवर्ष में छठा, क्रांति दिवस। 7 फ़्रुक्टिडोर वर्ष III (24 अगस्त 1795) के एक आदेश ने इनका नाम बदलकर <em>jours complémentaires</em> (पूरक दिन) कर दिया। चूँकि नया वर्ष किसी निश्चित नियम के बजाय विषुव के अनुसार चलता था, अधिवर्ष वहीं पड़े जहाँ खगोलशास्त्र ने उन्हें रखा: वर्ष III, VII और XI। मानचित्र 22 सितंबर 1795 को <em>Jour de la Révolution, an III</em> के रूप में दिखाता है।</p><h3>गाँव-देहात से लिए गए नाम</h3><p>महीनों के नाम कवि और अभिनेता <strong>फ़ाब्र देग्लांतीन</strong> ने गढ़े थे, और 24 अक्टूबर 1793 को इन्हें स्वीकृति मिली। इनके अंत ऋतु का संकेत देते हैं। शरद के महीनों के अंत में <em>-aire</em> है: वांदेमियेर (अंगूर की फ़सल), ब्रूमेर (कुहासा), फ़्रिमेर (पाला)। शीत के <em>-ôse</em>: निवोज़ (हिम), प्लुवियोज़ (वर्षा), वांतोज़ (हवा)। वसंत के <em>-al</em>: जर्मिनल (अंकुरण), फ़्लोरेयाल (फूल), प्रेरियाल (घास के मैदान)। ग्रीष्म के <em>-idor</em>: मेसिडोर (फ़सल कटाई), थर्मिडोर (गर्मी), फ़्रुक्टिडोर (फल)। जनवरी 1800 की <em>Sporting Magazine</em> में एक ब्रिटिश व्यंग्यकार ने पूरी सूची को तुकबंद अंग्रेज़ी उपनामों में ढाल दिया: Wheezy, Sneezy, Freezy; Slippy, Drippy, Nippy; Showery, Flowery, Bowery; Hoppy, Croppy, Poppy।</p><p>कैथोलिक कैलेंडर के संतों को भी हटा दिया गया। फ़ाब्र ने, जार्दें दे प्लांत (Jardin des Plantes) के माली आंद्रे तुएँ की मदद से, हर दिन को ग्रामीण जीवन से जुड़ा एक नाम दिया। हर <em>quintidi</em> (5, 15 और 25 तारीख़) किसी पशु के नाम पर है, हर <em>décadi</em> खेती के किसी औज़ार के नाम पर, और बाक़ी ज़्यादातर दिन पौधों के नाम पर। ब्रूमेर में 5 तारीख़ <em>Oie</em> (कलहंस) है और 10 तारीख़ <em>Charrue</em> (हल)। फ़ाब्र इन नामों को पूरे एक वर्ष तक प्रयोग में आते नहीं देख पाए: 5 अप्रैल 1794, यानी 16 जर्मिनल वर्ष II को, दांतों के समर्थकों के साथ उन्हें गिलोटिन पर चढ़ा दिया गया।</p><h3>तिथियाँ जो नाम बन गईं</h3><p><strong>9 थर्मिडोर वर्ष II</strong> (27 जुलाई 1794) को, जो ब्लैकबेरी (<em>Mûre</em>) के नाम का दिन था, कन्वेंशन ने रोबेस्पियेर की गिरफ़्तारी का आदेश दिया, और अगले दिन, 10 थर्मिडोर को, जो झारे (<em>Arrosoir</em>) का दिन था, उन्हें गिलोटिन पर चढ़ा दिया गया। उनके पतन के बाद के दौर को थर्मिडोरी प्रतिक्रिया कहा जाता है। <strong>18 ब्रूमेर वर्ष VIII</strong> (9 नवंबर 1799) को, चित्रक (<em>Dentelaire</em>) के दिन, नेपोलियन बोनापार्ट ने वह तख़्तापलट शुरू किया जिसने उन्हें प्रथम कॉन्सल बना दिया। कार्ल मार्क्स ने 1852 में इसी तिथि को अपनी कृति <em>लुई बोनापार्ट का अठारहवाँ ब्रूमेर</em> के शीर्षक में इस्तेमाल किया, जो 2 दिसंबर 1851 को नेपोलियन के भतीजे द्वारा किए गए तख़्तापलट के बारे में है। मानचित्र इन दोनों दिनों को <em>Nonidi 9 Thermidor an II</em> और <em>Octidi 18 Brumaire an VIII</em> के रूप में दिखाता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1794-07-27\" data-cal=\"french_rep\">📅 9 थर्मिडोर वर्ष II (27 जुलाई 1794) पर जाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1799-11-09\" data-cal=\"french_rep\">📅 18 ब्रूमेर वर्ष VIII (9 नवंबर 1799) पर जाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1871-05-06\" data-cal=\"french_rep\">📅 16 फ़्लोरेयाल वर्ष LXXIX (6 मई 1871) पर जाएँ</button></div><h3>उन्मूलन, और 1871 में वापसी</h3><p>बोनापार्ट के शासन में कैलेंडर को चरणबद्ध ढंग से समाप्त किया गया। 7 थर्मिडोर वर्ष VIII (26 जुलाई 1800) के एक आदेश ने <em>décadi</em> का विश्राम दिवस केवल सरकारी कर्मचारियों तक सीमित कर दिया, और 18 जर्मिनल वर्ष X (8 अप्रैल 1802) के क़ानून ने, जिसके ज़रिए पोप के साथ कॉनकॉर्डेट प्रख्यापित हुआ, उनका विश्राम दिवस भी रविवार को कर दिया। 22 फ़्रुक्टिडोर वर्ष XIII (9 सितंबर 1805) के एक <em>senatus-consultum</em> (सीनेट-आदेश) ने, जिसे एक आयोग ने तैयार किया था और जिसकी रिपोर्ट पियेर-सिमों लाप्लास ने प्रस्तुत की थी, 11 निवोज़ वर्ष XIV यानी 1 जनवरी 1806 से ग्रेगोरियन कैलेंडर बहाल कर दिया। आधिकारिक प्रयोग में अंतिम गणतंत्रीय तिथि थी <em>Décadi 10 Nivôse an XIV</em>, यानी 31 दिसंबर 1805।</p><p>यह कैलेंडर एक बार लौटा। मई 1871 में पेरिस कम्यून के <em>Journal officiel</em> ने फिर से गणतंत्रीय तिथियों का प्रयोग किया: 6 मई के आदेशों पर 16 फ़्लोरेयाल वर्ष LXXIX की तिथि है, और बाद के अंकों में पृष्ठ के शीर्ष पर ग्रेगोरियन तिथि के साथ गणतंत्रीय तिथि भी छापी गई। इस पुनरुद्धार को आम तौर पर अठारह दिनों का माना जाता है, 16 फ़्लोरेयाल से 3 प्रेरियाल (6 से 23 मई) तक। उसी महीने के अंतिम सप्ताह में कम्यून को कुचल दिया गया।</p>","maya-long-count-2012":"<h3>दिनों के पाँच स्थान</h3><p>माया दीर्घ गणना एक निश्चित आधार-तिथि से बीते दिनों का लगातार चलता योग है, जिसे पाँच स्थानों में लिखा जाता है। एक <em>k’in</em> एक दिन है; 20 किन से एक <em>winal</em> बनता है; 18 विनाल से 360 दिनों का एक <em>tun</em>; 20 तुन से 7,200 दिनों का एक <em>k’atun</em>; और 20 कातुन से 1,44,000 दिनों का एक <em>b’ak’tun</em>। यह गणना 20 के आधार पर चलती है, सिवाय तुन के स्थान के, जहाँ 18 का गुणक इकाई को सौर वर्ष के क़रीब रखता है। स्मारकों पर दिन का स्थान 260-दिवसीय <em>tzolk’in</em> और 365-दिवसीय <em>haab’</em> में भी जोड़ा जाता था।</p><p>आधार-तिथि 13.0.0.0.0 4 Ajaw 8 Kumk’u है। गुडमैन–मार्तीनेस–थॉम्पसन (GMT) सहसंबंध, जिसे अधिकांश माया-विद्वान अपनाते हैं, इसे जूलियन दिन संख्या 5,84,283 के बराबर मानता है: पूर्वव्यापी ग्रेगोरियन कैलेंडर में 11 अगस्त 3114 ईसा पूर्व। प्रतिद्वंद्वी स्थिरांक 5,84,285 हर तिथि को दो दिन आगे खिसका देता है। दीर्घ गणना की सबसे पुरानी बची हुई तिथियाँ माया क्षेत्र के बाहर से मिली हैं, चियापा दे कोर्सो का स्तंभ 2 (36 ईसा पूर्व) और त्रेस सापोतेस का स्तंभ C (32 ईसा पूर्व); माया राजाओं ने इन्हें तिकाल के स्तंभ 29 (292 ईस्वी) से लेकर तोनिना में 10.4.0.0.0, यानी 13 जनवरी 909 (जूलियन) तक उकेरा।</p><h3>21 दिसंबर 2012</h3><p>आधार-तिथि पर बक्तुन का स्थान 13 पढ़ता था; अगले दिन गणना 0.0.0.0.1 से फिर शुरू हुई। तेरह बक्तुन 18,72,000 दिन होते हैं, लगभग 5,125 वर्ष, इसलिए 21 दिसंबर 2012 को बक्तुन का स्थान फिर 13 पर पहुँचा: 13.0.0.0.0 4 Ajaw 3 K’ank’in (584,285 स्थिरांक के अनुसार 23 दिसंबर)। प्रलय वाली व्याख्या आधुनिक है। <em>The Maya</em> (1966) के पहले संस्करण में माइकल को ने सुझाया कि माया लोग 13वें बक्तुन के पूरा होने पर संसार के विनाश की अपेक्षा करते थे, और उस दिन को तब उन्होंने 24 दिसंबर 2011 माना। होसे अर्गुएयेस की <em>The Mayan Factor</em> (1987) ने 21 दिसंबर 2012 को ब्रह्मांडीय तालमेल की तिथि बना दिया, और उसके बाद किताबें और फ़िल्में आईं, जिनमें रोलैंड एमेरिख की <em>2012</em> (2009) तक शामिल है।</p><h3>अभिलेख क्या कहते हैं</h3><p>दो ज्ञात क्लासिक पाठ इस तिथि का उल्लेख करते हैं। ताबास्को से मिला तोर्तुगेरो स्मारक 6 शासक बहलाम अजाउ द्वारा 9.11.16.8.18 (11 जनवरी 669, जूलियन) को एक भवन के समर्पण का विवरण देता है। इसकी अंतिम पंक्तियाँ 4 Ajaw 3 K’ank’in को 13वें बक्तुन के पूरा होने की ओर देखती हैं और एक देवता, बोलोन योक्ते कुह, का नाम लेती हैं। क्रिया घिस चुकी है: स्टीफ़न ह्यूस्टन और डेविड स्टुअर्ट (1996) ने इसे <em>उतरना</em> पढ़ा, जबकि स्वेन ग्रोनमायर और बारबरा मैकलियोड (2010) ने इसे राज्याभिषेक समारोह में देवता का सार्वजनिक प्रदर्शन माना। स्टुअर्ट बाद में इस निष्कर्ष पर पहुँचे कि भविष्य की यह तिथि एक स्थानीय घटना को समय में स्थापित करती है और यह कोई भविष्यवाणी नहीं है।</p><p>दूसरा पाठ 2012 में ग्वाटेमाला के ला कोरोना में चित्रलिपि सीढ़ी 2 पर मिला। कालाकमुल के राजा युकनूम यिचाक काक ने 696 में वहाँ की यात्रा की और 692 के कातुन-समापन 9.13.0.0.0 के बाद स्वयं को <em>13 कातुन का स्वामी</em> कहा; पाठ उस समापन को 13वें बक्तुन से जोड़ता है। उत्खनन के सह-निदेशक मार्चेलो कानूतो ने टुलेन विश्वविद्यालय की घोषणा में कहा: “यह पाठ भविष्यवाणी के बजाय प्राचीन राजनीतिक इतिहास की बात करता है।”</p><p>दूसरे पाठ 2012 से आगे तक गिनते हैं। पालेंके के अभिलेख-मंदिर का एक पट्ट किनिच हानाब पकाल के राज्यारोहण के बाद 80वें कैलेंडर चक्र (18,980 दिन, लगभग 52 वर्ष) को 1.0.0.0.0.8 5 Lamat 1 Mol, यानी 21 अक्टूबर 4772 ईस्वी, तक आगे बढ़ाता है। छठा स्थान 20 बक्तुन का <em>piktun</em> है: अपेक्षा यह थी कि बक्तुन का स्थान 13 से आगे 19 तक चलेगा।</p><h3>गणना जो चलती रही</h3><p>10वीं सदी के बाद दीर्घ गणना उकेरी जानी बंद हो गई; 260-दिवसीय गणना कभी नहीं छोड़ी गई। मोमोस्तेनांगो और ग्वाटेमाला के अन्य पहाड़ी कस्बों में किचे दिन-पालक (<em>ajq’ijab’</em>) इसे अनुष्ठानों, शकुन-विचार और नामकरण के लिए बनाए रखते हैं, जैसा कि बारबरा टेडलॉक ने <em>Time and the Highland Maya</em> (1982) में दर्ज किया। इसके 20 दिन किचे नामों के साथ क्लासिक दिनों से स्थान-दर-स्थान मेल खाते हैं: जहाँ क्लासिक पाठों में Ajaw है, वहाँ Ajpu आता है। 21 दिसंबर 2012 को गणना 4 Ajpu पर थी, और अगले दिन 5 Imox पर। नए दिन-पालकों की दीक्षा Wajxaqib’ B’atz’ (8 B’atz’) को होती है, जो हर 260 दिन पर लौटता है: 18 जनवरी 2025, 5 अक्टूबर 2025, 22 जून 2026, 9 मार्च 2027।</p><p>मध्य मेक्सिको ने स्पेनी विजय तक यही गणना <em>tonalpohualli</em> के रूप में, नाहुआत्ल दिन-चिह्नों के साथ, बनाए रखी। कासो सहसंबंध, जो तेनोच्तित्लान के पतन को 13 अगस्त 1521 (जूलियन) को 1 Coatl (1 सर्प) पर रखता है, इसे माया गणना से दिन-दर-दिन मिलाता है: 21 दिसंबर 2012 Nahui Xochitl, यानी 4 पुष्प, था, वह चिह्न जो उस स्थान पर है जहाँ माया में Ajaw है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"2012-12-21\" data-cal=\"maya\">📅 तारीख़ 21 दिसंबर 2012 (13.0.0.0.0) पर सेट करें</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"kiche\">🗓️ किचे दिन-गणना दिखाएँ</button></div>","chinese-lunisolar-solar-terms":"<h3>महीना चंद्रमा का, पद सूर्य का</h3><p>चीनी पंचांग का हर महीना अमावस्या के दिन शुरू होता है, जिसकी गणना बीजिंग समय (UTC+8, 120° पूर्वी देशांतर) के अनुसार होती है। एक महीने में 29 या 30 दिन होते हैं, और बारह महीने मिलकर लगभग 354 दिन बनते हैं, जो सौर वर्ष से ग्यारह दिन कम हैं। हेल्मर आस्लाक्सन अपनी पुस्तक <em>The Mathematics of the Chinese Calendar</em> में साफ़ शब्दों में कहते हैं: \"ध्यान दीजिए कि चीनी पंचांग चांद्र पंचांग नहीं है!\"</p><p>सौर हिस्सा है <strong>24 सौर पद</strong> (节气 <em>jiéqì</em>), जो सूर्य के मार्ग पर 15° के अंतर पर स्थित बिंदु हैं: 立春 वसंत आरंभ लगभग 4 फ़रवरी को, 春分 मार्च विषुव, 冬至 दिसंबर अयनांत। जिन बारह पदों में अयनांत और विषुव शामिल हैं, वे प्रधान पद हैं, 中气 <em>zhōngqì</em>। चूँकि ये सूर्य का अनुसरण करते हैं, इसलिए पद हर साल लगभग एक ही ग्रेगोरियन तारीख़ों पर पड़ते हैं — 清明 चिंगमिंग हमेशा 4 से 6 अप्रैल के बीच — जबकि उनकी चांद्र तारीख़ें एक महीने तक खिसक जाती हैं। यूनेस्को ने 2016 में 24 सौर पदों को अमूर्त सांस्कृतिक विरासत की सूची में शामिल किया।</p><h3>अधिमास का नियम</h3><p>प्रधान पद ही महीनों की संख्या तय करते हैं: जिस महीने में 冬至 पड़ता है, वह हमेशा 11वाँ होता है, और जिसमें 雨水 वर्षा जल पड़ता है, वह पहला। औसतन 19 वर्षों में सात बार कोई चांद्र महीना दो प्रधान पदों के बीच पड़ जाता है और उसमें एक भी प्रधान पद नहीं होता। वही महीना अधिमास, 闰月, होता है और वह अपने से पिछले महीने की संख्या दोहराता है। <em>हान शू</em> में यह नियम यूँ लिखा है: 朔不得中，是謂閏月, यानी जो अमावस्या किसी प्रधान पद तक नहीं पहुँचती, उससे अधिमास बनता है; और यह नियम 104 ईसा पूर्व के ताइचू पंचांग से लागू है।</p><p>1645 में जो बदला, वह था सूर्य। नए छिंग राजवंश के लिए जेसुइट पादरी एडम शाल फ़ॉन बेल द्वारा तैयार किए गए शीश्यान पंचांग 时宪历 ने माध्य सूर्य के आधार पर बराबर अंतर वाले पदों (平气) की जगह वास्तविक सूर्य के आधार पर तय पद (定气) अपनाए। उत्तरी गोलार्ध की सर्दियों में सूर्य सबसे तेज़ चलता है, इसलिए अब प्रधान पद सर्दियों में 29.44 दिन और गर्मियों में 31.44 दिन के अंतर पर पड़ते हैं, और सर्दी के एक महीने में दो प्रधान पद भी आ सकते हैं। इसलिए चीन के राष्ट्रीय मानक GB/T 33661-2017 में तय आधुनिक नियम एक 11वें महीने से अगले 11वें महीने के बीच प्रधान पद से रहित पहले महीने को अधिमास मानता है। अब अधिमास ज़्यादातर गर्मियों में पड़ते हैं। सबसे हालिया अधिमास 2025 का अधिक छठा महीना था, 25 जुलाई से 22 अगस्त तक: 大暑 महाग्रीष्म 22 जुलाई को छठे महीने में पड़ा, और 处暑 ग्रीष्मांत 23 अगस्त को, जो सातवें महीने का पहला दिन था। 乙巳 वर्ष 29 जनवरी 2025 से 16 फ़रवरी 2026 तक, कुल 384 दिन का रहा।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"2026-02-17\" data-cal=\"chinese\">📅 चांद्र नववर्ष 2026: 17 फ़रवरी</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"vietnamese\">🗓️ वियतनामी चांद्र पंचांग दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setdate\" data-date=\"1968-01-29\" data-cal=\"vietnamese\">📅 29 जनवरी 1968: हनोई में तेत</button></div><h3>नियम वही, घड़ियाँ अलग</h3><p>कोरिया और वियतनाम यही नियम अपनाते हैं, पर गणना UTC+9 और UTC+7 के लिए करते हैं। ऐसे में आधी रात के आसपास पड़ने वाली अमावस्या या प्रधान पद अलग-अलग तारीख़ों पर जा पड़ता है। जैसा कि कोरिया खगोल विज्ञान एवं अंतरिक्ष विज्ञान संस्थान के पार्क सोक-जे ने 2014 में <em>सेग्ये इल्बो</em> में समझाया, 2012 में पाँचवें महीने की शुरुआत करने वाली अमावस्या चीन में 19 जून को 23:02 पर और कोरिया में 20 जून को 0:02 पर पड़ी। उस वर्ष कोरिया में तीसरा महीना अधिमास बना और चीन में चौथा: कोरिया में 소만 अन्न-पूर्णता 21 मई को, यानी चौथे महीने के पहले दिन पड़ा, जिससे उससे पहले का महीना बिना किसी प्रधान पद के रह गया। 1985 में वियतनाम ने तेत 21 जनवरी को मनाया, जबकि चीन ने अपना नववर्ष 20 फ़रवरी को।</p><p>वियतनाम के राशिचक्र में शाखा 卯 <em>Mão</em> का चौथा पशु खरगोश नहीं, बल्कि बिल्ली (<em>mèo</em>) है, और 丑 <em>Sửu</em> जल-भैंस (<em>trâu</em>) है। 2023, Quý Mão, हनोई में बिल्ली का वर्ष था और बीजिंग व सियोल में खरगोश का।</p><h3>1968 में तेत की दो तारीख़ें</h3><p>8 अगस्त 1967 को उत्तरी वियतनाम की सरकार ने (निर्णय 121/CP) उत्तर का आधिकारिक समय UTC+7 तय किया और उसी समय-क्षेत्र के लिए गणना किए गए चांद्र पंचांग को मंज़ूरी दी; दक्षिण ने बीजिंग के देशांतर पर आधारित पुरानी गणना जारी रखी। तेत 1968 की अमावस्या 29 जनवरी को 16:29 UTC पर पड़ी: हनोई में यह 23:29 था, इसलिए वहाँ तेत 29 जनवरी को हुआ, जबकि पुरानी गणना से यह 30 जनवरी को 0:15 था, इसलिए साइगॉन का तेत 30 जनवरी को हुआ। आस्लाक्सन एक वियतनामी वेबसाइट का हवाला देते हुए इसे तेत आक्रमण से जोड़ते हैं। आदेश तेत के दूसरे दिन तड़के हमला करने का था; दा नांग और मध्य भाग के अन्य शहरों की इकाइयों ने, जिन्हें नए पंचांग की जानकारी थी, 30 जनवरी की सुबह हमला कर दिया, जबकि साइगॉन और उसके दक्षिण के शहरों में हमला 31 जनवरी को हुआ।</p>","thai-buddhist-era":"<p>थाईलैंड अपने वर्षों की गिनती <strong>बौद्ध संवत्</strong> (พุทธศักราช, संक्षेप में พ.ศ.) में करता है, जो बुद्ध के परिनिर्वाण से गिना जाता है। थाई कैलेंडर पश्चिमी गणना से अंतर को ठीक 543 वर्ष पर स्थिर रखता है, इसलिए 2026 बौद्ध संवत् 2569 है। महीने और दिन ग्रेगोरियन ही हैं, केवल वर्ष की संख्या अलग है। मानचित्र पर 1 जनवरी 1941 थाई अंकों में <strong>๑ มกราคม พ.ศ. ๒๔๘๔</strong> के रूप में दिखता है।</p><h3>बैंकॉक का अपना संवत्, 1889–1913</h3><p>सौर कैलेंडर बौद्ध गणना से नया है। 1889 से पहले स्याम में दस्तावेज़ों पर तिथियाँ चांद्र-सौर कैलेंडर और चुल शकराज संवत् के अनुसार डाली जाती थीं; इसके महीने चंद्रमा के साथ चलते थे और इसमें अधिमास और अतिरिक्त दिन जोड़ने पड़ते थे। राजा चुलालोंगकोर्न के नाम से जारी और चुल शकराज 1250 (1888) की तिथि वाली एक राजघोषणा ने 1 अप्रैल 1889 से इस व्यवस्था की जगह ले ली। इसने सौर वर्ष और एक नया संवत् शुरू किया — <strong>रत्नकोसिन संवत्</strong> (รัตนโกสินทรศก, ร.ศ.), जिसे 1782 में बैंकॉक के राजधानी बनने के बाद से बीते वर्षों की गिनती के रूप में परिभाषित किया गया। वह पहला दिन मानचित्र पर <strong>๑ เมษายน ร.ศ. ๑๐๘</strong> के रूप में दिखता है।</p><p>नए महीनों के नाम संस्कृत में राशियों के नाम पर रखे गए। अप्रैल, เมษายน <em>mesayon</em>, मेष राशि और <em>āyana</em> (आयन), \"आगमन\", से मिलकर बना है। तीस दिन वाले महीनों के नाम <em>-ayon</em> पर और इकतीस दिन वाले महीनों के नाम <em>-akhom</em> (संस्कृत <em>āgama</em>, आगम) पर समाप्त होते हैं। फ़रवरी, जो अकेला छोटा महीना है, <em>-aphan</em> पर समाप्त होता है, जो <em>bandha</em> (बंध), \"बँधा हुआ\", से आया है।</p><p>राजा वजिरावुध ने 24 वर्ष बाद यह संवत् समाप्त कर दिया। रत्नकोसिन संवत् 131 की 21 फ़रवरी की तिथि वाली उनकी घोषणा में कहा गया कि 1782 से शुरू होने वाला संवत् वर्तमान और भविष्य के लिए तो उपयुक्त है, पर अतीत के लिए नहीं, क्योंकि उससे पुरानी हर बात को रत्नकोसिन संवत् से पहले के वर्षों के रूप में उल्टा गिनना पड़ता। 1 अप्रैल 1913 से आधिकारिक वर्ष बौद्ध संवत् 2456 हो गया, और पुराने संवत् से बदलने के लिए 2,324 जोड़ना होता है। थाई वर्ष तब भी अप्रैल से शुरू होता था, इसलिए रत्नकोसिन संवत् 131 की 21 फ़रवरी फ़रवरी 1913 में पड़ी, 1912 में नहीं।</p><h3>नौ महीने चला साल</h3><p>प्लैक फिबुनसोंगख्राम की सरकार ने सितंबर 1940 में पारित बौद्ध संवत् 2483 के कैलेंडर वर्ष अधिनियम के ज़रिए नववर्ष को 1 अप्रैल से हटाकर 1 जनवरी कर दिया। बौद्ध संवत् 2483 1 अप्रैल 1940 को शुरू हुआ था और नौ महीने बाद, 31 दिसंबर 1940 को समाप्त हो गया। अगला दिन बौद्ध संवत् 2484 की 1 जनवरी था।</p><p>इससे पुराने दस्तावेज़ों में एक जाल छिपा रह जाता है। 1941 से पहले की जनवरी, फ़रवरी या मार्च की किसी तिथि के लिए पश्चिमी वर्ष बौद्ध वर्ष में से 542 घटाकर मिलता है, 543 नहीं। बौद्ध संवत् 2481 के मार्च में दर्ज कोई जन्म मार्च 1939 में हुआ था।</p><h3>एक बुद्ध, दो वर्ष-संख्याएँ</h3><p>श्रीलंका, म्यांमार और कंबोडिया भी बौद्ध संवत् का उपयोग करते हैं, पर वे हर नया बौद्ध वर्ष मई में वेसाक से शुरू करते हैं, और तब से पश्चिमी वर्ष के अंत तक उनकी गणना थाईलैंड से एक वर्ष आगे रहती है। श्रीलंका में लोक प्रशासन मंत्रालय ने मई 2025 के राजकीय वेसाक समारोह से जुड़े अपने परिपत्र का शीर्षक रखा: \"राजकीय वेसाक समारोह का स्मरणोत्सव – बौद्ध संवत् 2569\"। थाईलैंड में 2025 बौद्ध संवत् 2568 था। कंबोडिया ने 2017 को बौद्ध संवत् 2561 कहा, जबकि थाईलैंड ने 2560।</p><p>नतीजतन 2,500वाँ वर्ष दो बार मनाया गया। रंगून में बर्मा की छठी बौद्ध संगीति 17 मई 1954 को वेसाक के दिन शुरू हुई, ताकि वह 24 मई 1956 को वेसाक के दिन — परिनिर्वाण की पारंपरिक 2,500वीं वर्षगाँठ पर — समाप्त हो सके। भारत ने उसी महीने 2,500वीं बुद्ध जयंती के समारोह आयोजित किए। थाईलैंड ने 25वीं बौद्ध शताब्दी मई 1957 में मनाई, जो उसकी गणना से बौद्ध संवत् 2500 था। उस उत्सव की मुख्य परियोजनाओं में से एक बैंकॉक के पश्चिम में सालाया स्थित फुत्थमोंथोन पार्क था।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"buddhist\">🗓️ थाई सौर कैलेंडर देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-cal=\"rattanakosin\">🗓️ रत्नकोसिन संवत् देखें</button></div>"};
